package ec.edu.ups.restaurant.menu;

import ec.edu.ups.restaurant.security.Tenant;
import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import java.math.BigDecimal;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import org.springframework.core.io.buffer.DataBufferUtils;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.http.codec.multipart.FilePart;
import org.springframework.r2dbc.core.DatabaseClient;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.transaction.reactive.TransactionalOperator;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

@RestController
@RequestMapping("/api/v1")
public class MenuController {
  private static final int MAX_IMAGE_BYTES = 2 * 1024 * 1024;
  private static final Set<String> IMAGE_TYPES = Set.of(MediaType.IMAGE_JPEG_VALUE, MediaType.IMAGE_PNG_VALUE, "image/webp");
  private final DatabaseClient db; private final TransactionalOperator tx;
  public MenuController(DatabaseClient db, TransactionalOperator tx) { this.db = db; this.tx = tx; }
  public record Category(UUID id, String name, String description, int displayOrder, boolean active) {}
  public record CategoryInput(@NotBlank String name, String description, int displayOrder, boolean active) {}
  public record VariantInput(@NotNull UUID presentationId, @NotNull @DecimalMin("0.01") BigDecimal price, boolean active) {}
  public record ExtraInput(@NotNull UUID ingredientId, @NotNull @DecimalMin("0.00") BigDecimal surcharge, boolean active) {}
  public record IngredientInput(@NotNull UUID ingredientId, boolean removable) {}
  public record InstructionInput(@NotBlank String instruction, boolean active) {}
  public record DishInput(@NotNull UUID categoryId, @NotBlank String name, String description, String informationalIngredients, boolean active, @NotEmpty List<@Valid VariantInput> variants, List<@Valid ExtraInput> extras, List<@Valid IngredientInput> ingredients, List<@Valid InstructionInput> instructions) {}
  public record DishUpdateInput(@NotNull UUID categoryId, @NotBlank String name, String description, @NotNull UUID presentationId, @NotNull @DecimalMin("0.01") BigDecimal price, @NotNull List<@Valid ExtraInput> extras, @NotNull List<@Valid IngredientInput> ingredients) {}
  public record ActiveInput(boolean active) {}
  public record Variant(UUID id, String name, BigDecimal price, boolean active, Integer onHand, Integer reserved, boolean soldOut, boolean tracked) {
    /** Vendible ahora: activa, no agotada y, si controla cantidad, con unidades libres. */
    boolean sellable() { return active && !soldOut && (!tracked || onHand - reserved > 0); }
  }
  public record Option(UUID id, String name, BigDecimal surcharge, Boolean removable, Boolean active) {}
  public record Dish(UUID id, UUID categoryId, String category, String name, String description, String ingredients, boolean active, boolean available, boolean hasImage, List<Variant> variants, List<Option> extras, List<Option> removableIngredients, List<Option> instructions) {}

  @GetMapping("/menu/categories") public Flux<Category> categories() { return Tenant.restaurantId().flatMapMany(rest -> db.sql("SELECT id,name,description,display_order,active FROM category WHERE restaurante_id=:r ORDER BY display_order,name").bind("r", rest).map((row, metadata) -> new Category(row.get("id", UUID.class), row.get("name", String.class), row.get("description", String.class), row.get("display_order", Integer.class), row.get("active", Boolean.class))).all()); }
  @PostMapping("/admin/categories") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('ADMIN')") public Mono<Category> createCategory(@Valid @RequestBody CategoryInput input) { UUID id = UUID.randomUUID(); String name = input.name().trim(); return Tenant.restaurantId().flatMap(rest -> categoryNameTaken(rest, name, null).flatMap(taken -> taken ? Mono.error(new ResponseStatusException(HttpStatus.CONFLICT, "Ya existe una categoría con ese nombre")) : db.sql("INSERT INTO category(id,restaurante_id,name,description,display_order,active) VALUES(:id,:r,:n,:d,:o,:a)").bind("id", id).bind("r", rest).bind("n", name).bind("d", safe(input.description())).bind("o", input.displayOrder()).bind("a", input.active()).fetch().rowsUpdated().thenReturn(new Category(id, name, input.description(), input.displayOrder(), input.active())))); }
  @PutMapping("/admin/categories/{id}") @PreAuthorize("hasRole('ADMIN')") public Mono<Category> updateCategory(@PathVariable UUID id, @Valid @RequestBody CategoryInput input) { String name = input.name().trim(); return Tenant.restaurantId().flatMap(rest -> categoryExists(rest, id).flatMap(found -> { if (!found) return Mono.error(new ResponseStatusException(HttpStatus.NOT_FOUND, "Categoría no encontrada")); return categoryNameTaken(rest, name, id).flatMap(taken -> taken ? Mono.error(new ResponseStatusException(HttpStatus.CONFLICT, "Ya existe una categoría con ese nombre")) : db.sql("UPDATE category SET name=:n,description=:d,display_order=:o,active=:a WHERE id=:id AND restaurante_id=:r").bind("id", id).bind("r", rest).bind("n", name).bind("d", safe(input.description())).bind("o", input.displayOrder()).bind("a", input.active()).fetch().rowsUpdated().thenReturn(new Category(id, name, input.description(), input.displayOrder(), input.active()))); })); }
  @DeleteMapping("/admin/categories/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasRole('ADMIN')") public Mono<Void> deleteCategory(@PathVariable UUID id) { return Tenant.restaurantId().flatMap(rest -> db.sql("SELECT COUNT(d.id)::int uses FROM category c LEFT JOIN dish d ON d.category_id=c.id AND d.restaurante_id=c.restaurante_id WHERE c.id=:id AND c.restaurante_id=:r GROUP BY c.id").bind("id", id).bind("r", rest).map((row, metadata) -> row.get("uses", Integer.class)).one().switchIfEmpty(Mono.error(new ResponseStatusException(HttpStatus.NOT_FOUND, "Categoría no encontrada"))).flatMap(uses -> uses > 0 ? Mono.error(new ResponseStatusException(HttpStatus.CONFLICT, "No se puede eliminar una categoría con platos asociados")) : db.sql("DELETE FROM category WHERE id=:id AND restaurante_id=:r").bind("id", id).bind("r", rest).fetch().rowsUpdated().then())); }
  @GetMapping("/menu/dishes") public Flux<Dish> dishes() { return Tenant.restaurantId().flatMapMany(this::dishesFor); }
  @GetMapping("/menu/dishes/{id}") public Mono<Dish> dish(@PathVariable UUID id) { return Tenant.restaurantId().flatMap(rest -> dishFor(rest, id)); }
  @GetMapping("/menu/dishes/{id}/image") public Mono<ResponseEntity<byte[]>> image(@PathVariable UUID id) { return Tenant.restaurantId().flatMap(rest -> db.sql("SELECT content_type,image_data FROM dish_image WHERE restaurante_id=:r AND dish_id=:d").bind("r", rest).bind("d", id).map((row, metadata) -> ResponseEntity.ok().contentType(MediaType.parseMediaType(row.get("content_type", String.class))).body(row.get("image_data", byte[].class))).one().switchIfEmpty(Mono.error(new ResponseStatusException(HttpStatus.NOT_FOUND, "Imagen no encontrada")))); }
  @PostMapping("/admin/dishes") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('ADMIN')") public Mono<Dish> createDish(@Valid @RequestBody DishInput input) { return Tenant.restaurantId().flatMap(rest -> { UUID dishId = UUID.randomUUID(); Mono<Dish> work = db.sql("INSERT INTO dish(id,restaurante_id,category_id,name,description,informational_ingredients,active) SELECT :id,:r,:cat,:n,:d,:i,:a WHERE EXISTS(SELECT 1 FROM category WHERE id=:cat AND restaurante_id=:r)").bind("id", dishId).bind("r", rest).bind("cat", input.categoryId()).bind("n", input.name()).bind("d", safe(input.description())).bind("i", safe(input.informationalIngredients())).bind("a", input.active()).fetch().rowsUpdated().flatMap(rows -> rows == 0 ? Mono.error(new ResponseStatusException(HttpStatus.BAD_REQUEST, "Categoría inválida")) : insertOptions(rest, dishId, input).then(dishFor(rest, dishId))); return tx.transactional(work); }); }
   @PutMapping("/admin/dishes/{id}") @PreAuthorize("hasRole('ADMIN')") public Mono<Dish> updateDish(@PathVariable UUID id, @Valid @RequestBody DishUpdateInput input) { return Tenant.restaurantId().flatMap(rest -> tx.transactional(categoryExists(rest, input.categoryId()).flatMap(validCategory -> { if (!validCategory) return Mono.error(new ResponseStatusException(HttpStatus.BAD_REQUEST, "Categoría inválida")); return presentationName(rest, input.presentationId()).flatMap(presentation -> db.sql("UPDATE dish SET category_id=:category,name=:name,description=:description WHERE id=:id AND restaurante_id=:r").bind("category", input.categoryId()).bind("name", input.name().trim()).bind("description", safe(input.description())).bind("id", id).bind("r", rest).fetch().rowsUpdated().flatMap(rows -> rows == 0 ? Mono.error(new ResponseStatusException(HttpStatus.NOT_FOUND, "Plato no encontrado")) : updatePrimaryVariant(rest, id, presentation, input.price()).then(replaceDishOptions(rest, id, input)).then(dishFor(rest, id)))); }))); }
  @PatchMapping("/admin/dishes/{id}/active") @PreAuthorize("hasRole('ADMIN')") public Mono<Dish> updateDishActive(@PathVariable UUID id, @RequestBody ActiveInput input) { return Tenant.restaurantId().flatMap(rest -> db.sql("UPDATE dish SET active=:active WHERE id=:id AND restaurante_id=:r").bind("active", input.active()).bind("id", id).bind("r", rest).fetch().rowsUpdated().flatMap(rows -> rows == 0 ? Mono.error(new ResponseStatusException(HttpStatus.NOT_FOUND, "Plato no encontrado")) : dishFor(rest, id))); }
  @DeleteMapping("/admin/dishes/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasRole('ADMIN')") public Mono<Void> deleteDish(@PathVariable UUID id) { return Tenant.restaurantId().flatMap(rest -> tx.transactional(dishExists(rest, id).flatMap(found -> { if (!found) return Mono.error(new ResponseStatusException(HttpStatus.NOT_FOUND, "Plato no encontrado")); return hasAvailabilityMovements(rest, id).flatMap(hasMovements -> hasMovements ? Mono.error(new ResponseStatusException(HttpStatus.CONFLICT, "No se puede eliminar un plato con movimientos de disponibilidad")) : deleteDishData(rest, id)); }))); }
  @PostMapping(value = "/admin/dishes/{id}/image", consumes = MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasRole('ADMIN')") public Mono<Void> uploadImage(@PathVariable UUID id, @RequestPart("file") FilePart file) { MediaType contentType = file.headers().getContentType(); if (contentType == null || !IMAGE_TYPES.contains(contentType.toString())) return Mono.error(new ResponseStatusException(HttpStatus.BAD_REQUEST, "Formato de imagen no permitido")); return Tenant.restaurantId().flatMap(rest -> DataBufferUtils.join(file.content(), MAX_IMAGE_BYTES).onErrorMap(error -> new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE, "La imagen supera 2 MB")).flatMap(buffer -> { byte[] image = new byte[buffer.readableByteCount()]; buffer.read(image); DataBufferUtils.release(buffer); if (image.length == 0) return Mono.error(new ResponseStatusException(HttpStatus.BAD_REQUEST, "La imagen está vacía")); return db.sql("INSERT INTO dish_image(restaurante_id,dish_id,content_type,image_data) SELECT :r,:d,:t,:i WHERE EXISTS(SELECT 1 FROM dish WHERE id=:d AND restaurante_id=:r) ON CONFLICT(restaurante_id,dish_id) DO UPDATE SET content_type=EXCLUDED.content_type,image_data=EXCLUDED.image_data,updated_at=now()").bind("r", rest).bind("d", id).bind("t", contentType.toString()).bind("i", image).fetch().rowsUpdated().flatMap(rows -> rows == 0 ? Mono.error(new ResponseStatusException(HttpStatus.NOT_FOUND, "Plato no encontrado")) : Mono.empty()); })); }
  private Mono<Void> insertOptions(UUID rest, UUID dish, DishInput input) { return Flux.fromIterable(input.variants()).concatMap(variant -> presentationName(rest, variant.presentationId()).flatMap(name -> { UUID id = UUID.randomUUID(); return db.sql("INSERT INTO sellable_variant(id,restaurante_id,dish_id,name,price,active) VALUES(:id,:r,:d,:n,:p,:a)").bind("id", id).bind("r", rest).bind("d", dish).bind("n", name).bind("p", variant.price()).bind("a", variant.active()).fetch().rowsUpdated().then(db.sql("INSERT INTO availability(restaurante_id,variant_id,on_hand,reserved,sold_out,tracked) VALUES(:r,:id,0,0,false,false)").bind("r", rest).bind("id", id).fetch().rowsUpdated()); })).then().thenMany(Flux.fromIterable(orEmpty(input.extras())).concatMap(extra -> ingredientName(rest, extra.ingredientId()).flatMap(name -> db.sql("INSERT INTO extra_option(id,restaurante_id,dish_id,name,surcharge,active) VALUES(:id,:r,:d,:n,:p,:a)").bind("id", UUID.randomUUID()).bind("r", rest).bind("d", dish).bind("n", name).bind("p", extra.surcharge()).bind("a", extra.active()).fetch().rowsUpdated()))).then().thenMany(Flux.fromIterable(orEmpty(input.ingredients())).concatMap(ingredient -> ingredientName(rest, ingredient.ingredientId()).flatMap(name -> db.sql("INSERT INTO removable_ingredient(id,restaurante_id,dish_id,name,removable) VALUES(:id,:r,:d,:n,:x)").bind("id", UUID.randomUUID()).bind("r", rest).bind("d", dish).bind("n", name).bind("x", ingredient.removable()).fetch().rowsUpdated()))).then().thenMany(Flux.fromIterable(orEmpty(input.instructions())).concatMap(instruction -> db.sql("INSERT INTO preparation_instruction(id,restaurante_id,dish_id,instruction,active) VALUES(:id,:r,:d,:n,:a)").bind("id", UUID.randomUUID()).bind("r", rest).bind("d", dish).bind("n", instruction.instruction()).bind("a", instruction.active()).fetch().rowsUpdated())).then(); }
  private Mono<Void> updatePrimaryVariant(UUID rest, UUID dish, String presentation, BigDecimal price) { return db.sql("UPDATE sellable_variant SET name=:name,price=:price WHERE id=(SELECT id FROM sellable_variant WHERE restaurante_id=:r AND dish_id=:dish ORDER BY name LIMIT 1) AND restaurante_id=:r").bind("name", presentation).bind("price", price).bind("r", rest).bind("dish", dish).fetch().rowsUpdated().flatMap(rows -> rows == 0 ? Mono.error(new ResponseStatusException(HttpStatus.CONFLICT, "El plato no tiene una presentación editable")) : Mono.empty()); }
  private Mono<Void> replaceDishOptions(UUID rest, UUID dish, DishUpdateInput input) { return db.sql("DELETE FROM extra_option WHERE restaurante_id=:r AND dish_id=:d").bind("r", rest).bind("d", dish).fetch().rowsUpdated().then(db.sql("DELETE FROM removable_ingredient WHERE restaurante_id=:r AND dish_id=:d").bind("r", rest).bind("d", dish).fetch().rowsUpdated()).thenMany(Flux.fromIterable(input.extras()).concatMap(extra -> ingredientName(rest, extra.ingredientId()).flatMap(name -> db.sql("INSERT INTO extra_option(id,restaurante_id,dish_id,name,surcharge,active) VALUES(:id,:r,:d,:n,:p,:a)").bind("id", UUID.randomUUID()).bind("r", rest).bind("d", dish).bind("n", name).bind("p", extra.surcharge()).bind("a", extra.active()).fetch().rowsUpdated()))).then().thenMany(Flux.fromIterable(input.ingredients()).concatMap(ingredient -> ingredientName(rest, ingredient.ingredientId()).flatMap(name -> db.sql("INSERT INTO removable_ingredient(id,restaurante_id,dish_id,name,removable) VALUES(:id,:r,:d,:n,:x)").bind("id", UUID.randomUUID()).bind("r", rest).bind("d", dish).bind("n", name).bind("x", ingredient.removable()).fetch().rowsUpdated()))).then(); }
  private Mono<Void> deleteDishData(UUID rest, UUID dish) { return db.sql("DELETE FROM dish_image WHERE restaurante_id=:r AND dish_id=:d").bind("r", rest).bind("d", dish).fetch().rowsUpdated().then(db.sql("DELETE FROM extra_option WHERE restaurante_id=:r AND dish_id=:d").bind("r", rest).bind("d", dish).fetch().rowsUpdated()).then(db.sql("DELETE FROM removable_ingredient WHERE restaurante_id=:r AND dish_id=:d").bind("r", rest).bind("d", dish).fetch().rowsUpdated()).then(db.sql("DELETE FROM preparation_instruction WHERE restaurante_id=:r AND dish_id=:d").bind("r", rest).bind("d", dish).fetch().rowsUpdated()).then(db.sql("DELETE FROM availability WHERE restaurante_id=:r AND variant_id IN (SELECT id FROM sellable_variant WHERE restaurante_id=:r AND dish_id=:d)").bind("r", rest).bind("d", dish).fetch().rowsUpdated()).then(db.sql("DELETE FROM sellable_variant WHERE restaurante_id=:r AND dish_id=:d").bind("r", rest).bind("d", dish).fetch().rowsUpdated()).then(db.sql("DELETE FROM dish WHERE restaurante_id=:r AND id=:d").bind("r", rest).bind("d", dish).fetch().rowsUpdated()).then(); }
  private Flux<Dish> dishesFor(UUID rest) { return db.sql("SELECT d.id FROM dish d WHERE d.restaurante_id=:r ORDER BY d.name").bind("r", rest).map((row, metadata) -> row.get("id", UUID.class)).all().concatMap(id -> dishFor(rest, id)); }
  private Mono<Dish> dishFor(UUID rest, UUID id) { return db.sql("SELECT d.id,d.category_id,c.name category,d.name,d.description,d.informational_ingredients,d.active,EXISTS(SELECT 1 FROM dish_image di WHERE di.restaurante_id=d.restaurante_id AND di.dish_id=d.id) has_image FROM dish d JOIN category c ON c.id=d.category_id AND c.restaurante_id=d.restaurante_id WHERE d.id=:id AND d.restaurante_id=:r").bind("id", id).bind("r", rest).map((row, metadata) -> new DishBase(row.get("id", UUID.class), row.get("category_id", UUID.class), row.get("category", String.class), row.get("name", String.class), row.get("description", String.class), row.get("informational_ingredients", String.class), row.get("active", Boolean.class), row.get("has_image", Boolean.class))).one().switchIfEmpty(Mono.error(new ResponseStatusException(HttpStatus.NOT_FOUND, "Plato no encontrado"))).flatMap(base -> Mono.zip(variants(rest, id).collectList(), extras(rest, id).collectList(), ingredients(rest, id).collectList(), instructions(rest, id).collectList()).map(values -> new Dish(base.id, base.categoryId, base.category, base.name, base.description, base.ingredients, base.active, values.getT1().stream().anyMatch(Variant::sellable), base.hasImage, values.getT1(), values.getT2(), values.getT3(), values.getT4()))); }
  private Flux<Variant> variants(UUID restaurantId, UUID dishId) { return db.sql("SELECT v.id,v.name,v.price,v.active,a.on_hand,a.reserved,a.sold_out,a.tracked FROM sellable_variant v JOIN availability a ON a.variant_id=v.id AND a.restaurante_id=v.restaurante_id WHERE v.restaurante_id=:r AND v.dish_id=:d ORDER BY v.name").bind("r", restaurantId).bind("d", dishId).map((row, metadata) -> new Variant(row.get("id", UUID.class), row.get("name", String.class), row.get("price", BigDecimal.class), row.get("active", Boolean.class), row.get("on_hand", Integer.class), row.get("reserved", Integer.class), row.get("sold_out", Boolean.class), row.get("tracked", Boolean.class))).all(); }
  private Flux<Option> extras(UUID restaurantId, UUID dishId) { return db.sql("SELECT id,name,surcharge,active FROM extra_option WHERE restaurante_id=:r AND dish_id=:d ORDER BY name").bind("r", restaurantId).bind("d", dishId).map((row, metadata) -> new Option(row.get("id", UUID.class), row.get("name", String.class), row.get("surcharge", BigDecimal.class), null, row.get("active", Boolean.class))).all(); }
  private Flux<Option> ingredients(UUID restaurantId, UUID dishId) { return db.sql("SELECT id,name,removable FROM removable_ingredient WHERE restaurante_id=:r AND dish_id=:d ORDER BY name").bind("r", restaurantId).bind("d", dishId).map((row, metadata) -> new Option(row.get("id", UUID.class), row.get("name", String.class), BigDecimal.ZERO, row.get("removable", Boolean.class), true)).all(); }
  private Flux<Option> instructions(UUID restaurantId, UUID dishId) { return db.sql("SELECT id,instruction,active FROM preparation_instruction WHERE restaurante_id=:r AND dish_id=:d ORDER BY instruction").bind("r", restaurantId).bind("d", dishId).map((row, metadata) -> new Option(row.get("id", UUID.class), row.get("instruction", String.class), BigDecimal.ZERO, null, row.get("active", Boolean.class))).all(); }
  private Mono<String> presentationName(UUID rest, UUID id) { return catalogName("menu_presentation", rest, id, "Presentación inválida"); }
  private Mono<String> ingredientName(UUID rest, UUID id) { return catalogName("catalog_ingredient", rest, id, "Ingrediente inválido"); }
  private Mono<String> catalogName(String table, UUID rest, UUID id, String error) { return db.sql("SELECT name FROM " + table + " WHERE id=:id AND restaurante_id=:r AND active=true").bind("id", id).bind("r", rest).map((row, metadata) -> row.get("name", String.class)).one().switchIfEmpty(Mono.error(new ResponseStatusException(HttpStatus.BAD_REQUEST, error))); }
  private Mono<Boolean> categoryExists(UUID rest, UUID id) { return db.sql("SELECT EXISTS(SELECT 1 FROM category WHERE id=:id AND restaurante_id=:r) present").bind("id", id).bind("r", rest).map((row, metadata) -> row.get("present", Boolean.class)).one(); }
  private Mono<Boolean> dishExists(UUID rest, UUID id) { return db.sql("SELECT EXISTS(SELECT 1 FROM dish WHERE id=:id AND restaurante_id=:r) present").bind("id", id).bind("r", rest).map((row, metadata) -> row.get("present", Boolean.class)).one(); }
  private Mono<Boolean> hasAvailabilityMovements(UUID rest, UUID dish) { return db.sql("SELECT EXISTS(SELECT 1 FROM availability_movement m JOIN sellable_variant v ON v.id=m.variant_id AND v.restaurante_id=m.restaurante_id WHERE v.restaurante_id=:r AND v.dish_id=:d) present").bind("r", rest).bind("d", dish).map((row, metadata) -> row.get("present", Boolean.class)).one(); }
  private Mono<Boolean> categoryNameTaken(UUID rest, String name, UUID except) { String sql = "SELECT EXISTS(SELECT 1 FROM category WHERE restaurante_id=:r AND name=:n" + (except == null ? "" : " AND id<>:id") + ") present"; DatabaseClient.GenericExecuteSpec query = db.sql(sql).bind("r", rest).bind("n", name); if (except != null) query = query.bind("id", except); return query.map((row, metadata) -> row.get("present", Boolean.class)).one(); }
  private record DishBase(UUID id, UUID categoryId, String category, String name, String description, String ingredients, boolean active, boolean hasImage) {}
  private static String safe(String value) { return value == null ? "" : value; }
  private static <T> List<T> orEmpty(List<T> value) { return value == null ? List.of() : value; }
}
